281		err := os.Rename(src, dest)
282		if err == nil {
283			return nil
284		}
285		if runtime.GOOS == windowsGOOS {
286			if asideErr := os.Rename(dest, oldBinaryAsidePath(dest)); asideErr == nil {
287				if err = os.Rename(src, dest); err == nil {
288					return nil
289				}
290			}
291		}
292		// Cross-device rename: copy + fsync-free write, then remove src.
293		in, openErr := os.Open(src) //nolint:gosec // staging file we created
294		if openErr != nil {
295			return errors.Join(err, openErr)
296		}
297		defer in.Close()
298		if writeErr := writeExecutable(in, dest); writeErr != nil {
299			return errors.Join(err, writeErr)
300		}
301		_ = os.Remove(src)
302		return nil
303	}
304	
305	// oldBinaryAsidePath returns a unique .old- sibling path for the
306	// rename-aside trick. Random suffix so concurrent upgrades can't collide.
307	func oldBinaryAsidePath(dest string) string {
308		var b [4]byte
309		if _, err := rand.Read(b[:]); err != nil {
310			return dest + ".old-fallback"
311		}
312		return dest + ".old-" + hex.EncodeToString(b[:])
313	}
314	
315	// sweepOldBinaries best-effort removes .old-* leftovers from the Windows
316	// rename-aside fallback. Failures are ignored — the files are inert.
317	func sweepOldBinaries(pkgDir string) {
318		entries, err := os.ReadDir(pkgDir)
319		if err != nil {
320			return
321		}
322		for _, e := range entries {
323			if strings.Contains(e.Name(), ".old-") {
324				_ = os.Remove(filepath.Join(pkgDir, e.Name()))
325			}
326		}
327	}
328	
329	// RemoveManagedPlugin removes a plugin's bin entries and its pkg dir.
330	// The dependency guard lives in the command layer so --force can bypass it.
331	func RemoveManagedPlugin(name string) error {
332		if err := RemoveInstalledPlugin(name); err != nil {
333			return err
334		}
335		return RemovePluginPkg(name)
336	}
