30	// makeScriptTarGz builds a tar.gz holding an executable shell script named
31	// entire-<name> that echoes a version marker.
32	func makeScriptTarGz(t *testing.T, name, marker string) []byte {
33		t.Helper()
34		var buf bytes.Buffer
35		gz := gzip.NewWriter(&buf)
36		tw := tar.NewWriter(gz)
37		script := "#!/bin/sh\necho " + marker + "\n"
38		if err := tw.WriteHeader(&tar.Header{Name: "entire-" + name, Mode: 0o755, Size: int64(len(script)), Typeflag: tar.TypeReg}); err != nil {
39			t.Fatal(err)
40		}
41		if _, err := tw.Write([]byte(script)); err != nil {
42			t.Fatal(err)
43		}
44		if err := tw.Close(); err != nil {
45			t.Fatal(err)
46		}
47		if err := gz.Close(); err != nil {
48			t.Fatal(err)
49		}
50		return buf.Bytes()
51	}
52	
53	// startReleaseServer serves tar.gz assets for the named plugins/versions,
54	// plus the per-tag checksums.txt goreleaser publishes alongside them. Installs
55	// require an authenticated download by default, so serving checksums is what
56	// keeps these tests on the production code path rather than the refusal path.
57	func startReleaseServer(t *testing.T, plugins map[string][]string) *httptest.Server {
58		t.Helper()
59		assets := map[string][]byte{}
60		// Keyed by version: checksums.txt is per-tag and the URL template routes
61		// by tag, so the handler picks the manifest from the request path.
62		sumsByVersion := map[string][]byte{}
63		for name, versions := range plugins {
64			for _, v := range versions {
65				asset := fmt.Sprintf("entire-%s_%s_%s_%s.tar.gz", name, v, runtime.GOOS, runtime.GOARCH)
66				data := makeScriptTarGz(t, name, name+"-ran-v"+v)
67				assets[asset] = data
68				sumsByVersion[v] = append(sumsByVersion[v], []byte(fmt.Sprintf("%x  %s\n", sha256.Sum256(data), asset))...)
69			}
70		}
71		srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
72			base := r.URL.Path[strings.LastIndex(r.URL.Path, "/")+1:]
73			if base == "checksums.txt" {
74				for v, sums := range sumsByVersion {
75					if strings.Contains(r.URL.Path, "/v"+v+"/") || strings.Contains(r.URL.Path, "/"+v+"/") {
76						_, _ = w.Write(sums) //nolint:errcheck // test server write; failure surfaces as a client error
77						return
78					}
79				}
80				http.NotFound(w, r)
81				return
82			}
83			if data, ok := assets[base]; ok {
84				_, _ = w.Write(data) //nolint:errcheck // test server write; failure surfaces as a client error
85				return
86			}
87			http.NotFound(w, r)
88		}))
89		t.Cleanup(srv.Close)
90		return srv
91	}
