93	// newPluginRepo creates a tagged git repo with entire-plugin.yml.
94	func newPluginRepo(t *testing.T, metadata string, tags ...string) string {
95		t.Helper()
96		dir := t.TempDir()
97		testutil.InitRepo(t, dir)
98		testutil.WriteFile(t, dir, "entire-plugin.yml", metadata)
99		testutil.GitAdd(t, dir, "entire-plugin.yml")
100		testutil.GitCommit(t, dir, "init")
101		for _, tag := range tags {
102			if out, err := exec.CommandContext(t.Context(), "git", "-C", dir, "tag", tag).CombinedOutput(); err != nil {
103				t.Fatalf("git tag: %v: %s", err, out)
104			}
105		}
106		return "file://" + filepath.ToSlash(dir)
107	}
108	
109	// newIndexRepo creates a git repo holding index.json.
110	func newIndexRepo(t *testing.T, indexJSON string) string {
111		t.Helper()
112		dir := t.TempDir()
113		testutil.InitRepo(t, dir)
114		testutil.WriteFile(t, dir, "index.json", indexJSON)
115		testutil.GitAdd(t, dir, "index.json")
116		testutil.GitCommit(t, dir, "index")
