120	// pluginTestEnv builds the child env and the directory to run it from:
121	// isolated plugin dir + cache + index URL.
122	//
123	// The base MUST be testutil.GitIsolatedEnv(), not os.Environ(). The
124	// process-wide ENTIRE_TEST_GIT_HERMETIC=1 set by TestMain is inert on its own —
125	// it bites through the per-host http.<url>.proxy entries GitIsolatedEnv writes
126	// into an isolated GIT_CONFIG_GLOBAL, which point github.com/gitlab.com at a
127	// dead loopback address so a stray network dial fails fast instead of
128	// succeeding quietly. Building from os.Environ() sets the flag with no config
129	// backing it: tripwire absent, and the developer's real global git config
130	// inherited. That would let these tests pass by cloning the real
131	// entireio/plugin-index if index-URL resolution ever regressed to the built-in
132	// default — precisely the regression they exist to catch.
133	func pluginTestEnv(t *testing.T, indexURL string) (env []string, workDir string) {
134		t.Helper()
135		env = append(testutil.GitIsolatedEnv(),
136			"ENTIRE_PLUGIN_DIR="+t.TempDir(),
137			"XDG_CACHE_HOME="+t.TempDir(),
138		)
139		if indexURL != "" {
140			env = append(env, "ENTIRE_PLUGIN_INDEX_URL="+indexURL)
141		}
142		// A dedicated CWD, because settings resolve from the working directory: an
143		// unset cmd.Dir leaves the child standing in the real repo and reading its
144		// committed .entire/settings.json.
145		return env, t.TempDir()
146	}
