148	func runEntire(t *testing.T, env []string, workDir string, args ...string) (stdout, stderr string, err error) {
149		t.Helper()
150		cmd := execx.NonInteractive(context.Background(), getTestBinary(), args...)
151		cmd.Env = env
152		cmd.Dir = workDir
153		var out, errBuf bytes.Buffer
154		cmd.Stdout = &out
155		cmd.Stderr = &errBuf
156		err = cmd.Run()
157		return out.String(), errBuf.String(), err
158	}
