165		srv := startReleaseServer(t, map[string][]string{"demo": {"0.1.0"}})
166		repoURL := newPluginRepo(t, fmt.Sprintf("name: demo\ndownload_url: \"%s/dl/{tag}/{asset}\"\n", srv.URL), "v0.1.0")
167		indexURL := newIndexRepo(t, fmt.Sprintf(`{"version":1,"plugins":[{"name":"demo","repo_url":"%s","description":"Demo plugin","official":true}]}`, repoURL))
168		env, workDir := pluginTestEnv(t, indexURL)
169	
170		// Bare-name install resolves through the index; index-listed repos
171		// need no --yes.
172		stdout, stderr, err := runEntire(t, env, workDir, "plugin", "install", "demo")
173		if err != nil {
174			t.Fatalf("plugin install demo: %v\nstdout: %s\nstderr: %s", err, stdout, stderr)
175		}
176		if !strings.Contains(stdout, `Installed plugin "demo" v0.1.0`) {
177			t.Errorf("install output = %q", stdout)
178		}
179	
180		// The dispatcher must now run it as `entire demo`.
181		stdout, stderr, err = runEntire(t, env, workDir, "demo")
182		if err != nil {
183			t.Fatalf("entire demo: %v\nstderr: %s", err, stderr)
184		}
185		if !strings.Contains(stdout, "demo-ran-v0.1.0") {
186			t.Errorf("dispatched plugin output = %q, want demo-ran-v0.1.0", stdout)
187		}
188	
189		// list shows the tag from the manifest.
190		stdout, _, err = runEntire(t, env, workDir, "plugin", "list")
191		if err != nil {
192			t.Fatalf("plugin list: %v", err)
193		}
194		if !strings.Contains(stdout, "demo") || !strings.Contains(stdout, "v0.1.0") {
195			t.Errorf("plugin list output = %q, want name+tag", stdout)
196		}
197	}
