199	func TestPluginRemoteInstall_URLNeedsYesWhenUnlisted(t *testing.T) {
200		t.Parallel()
201		if runtime.GOOS == windowsGOOS {
202			t.Skip("shell-script plugin payloads are Unix-only")
203		}
204		srv := startReleaseServer(t, map[string][]string{"solo": {"0.1.0"}})
205		repoURL := newPluginRepo(t, fmt.Sprintf("name: solo\ndownload_url: \"%s/dl/{tag}/{asset}\"\n", srv.URL), "v0.1.0")
206		// Empty index: the URL is unlisted → untrusted.
207		indexURL := newIndexRepo(t, `{"version":1,"plugins":[]}`)
208		env, workDir := pluginTestEnv(t, indexURL)
