210		// Non-interactive without --yes refuses.
211		_, stderr, err := runEntire(t, env, workDir, "plugin", "install", repoURL)
212		if err == nil {
213			t.Fatal("unlisted URL install without --yes succeeded in non-interactive mode")
214		}
215		if !strings.Contains(stderr, "--yes") {
216			t.Errorf("stderr = %q, want a hint about --yes", stderr)
217		}
218	
219		// With --yes it proceeds.
220		stdout, stderr, err := runEntire(t, env, workDir, "plugin", "install", repoURL, "--yes")
221		if err != nil {
222			t.Fatalf("install --yes: %v\nstderr: %s", err, stderr)
223		}
224		if !strings.Contains(stdout, `Installed plugin "solo" v0.1.0`) {
225			t.Errorf("install output = %q", stdout)
226		}
227	}
