229	func TestPluginRemoteInstall_DependenciesAndRemoveGuard(t *testing.T) {
230		t.Parallel()
231		if runtime.GOOS == windowsGOOS {
232			t.Skip("shell-script plugin payloads are Unix-only")
233		}
234		srv := startReleaseServer(t, map[string][]string{"brainy": {"0.1.0"}, "semy": {"0.1.0"}})
235		semRepo := newPluginRepo(t, fmt.Sprintf("name: semy\ndownload_url: \"%s/dl/{tag}/{asset}\"\n", srv.URL), "v0.1.0")
236		brainRepo := newPluginRepo(t, fmt.Sprintf(
237			// requires[] has no repo_url any more; a leftover one must be ignored and
238			// the dependency resolved from the index. Point it somewhere unreachable
239			// so honoring it would fail the test loudly.
240			"name: brainy\ndownload_url: \"%s/dl/{tag}/{asset}\"\nrequires:\n  - name: semy\n    repo_url: https://unreachable.invalid/entire-semy\n", srv.URL), "v0.1.0")
241		indexURL := newIndexRepo(t, fmt.Sprintf(
242			`{"version":1,"plugins":[{"name":"brainy","repo_url":"%s"},{"name":"semy","repo_url":"%s"}]}`, brainRepo, semRepo))
243		env, workDir := pluginTestEnv(t, indexURL)
244	
245		stdout, stderr, err := runEntire(t, env, workDir, "plugin", "install", "brainy", "--yes")
246		if err != nil {
247			t.Fatalf("install brainy: %v\nstdout: %s\nstderr: %s", err, stdout, stderr)
248		}
249		if !strings.Contains(stdout, `Installed dependency "semy"`) {
250			t.Errorf("install output = %q, want dependency install", stdout)
251		}
252	
253		// Both dispatchable.
254		for _, name := range []string{"brainy", "semy"} {
255			out, _, err := runEntire(t, env, workDir, name)
256			if err != nil || !strings.Contains(out, name+"-ran-v0.1.0") {
257				t.Errorf("entire %s = %q, %v", name, out, err)
258			}
259		}
260	
261		// Remove guard: semy is required by brainy.
262		_, stderr, err = runEntire(t, env, workDir, "plugin", "remove", "semy")
263		if err == nil {
264			t.Fatal("remove of depended-on plugin succeeded without --force")
265		}
266		if !strings.Contains(stderr, "brainy") {
267			t.Errorf("remove stderr = %q, want dependent named", stderr)
268		}
269		if _, _, err := runEntire(t, env, workDir, "plugin", "remove", "semy", "--force"); err != nil {
270			t.Errorf("remove --force failed: %v", err)
271		}
272	
273		// Doctor now reports the missing dependency, exit code 1.
274		stdout, _, err = runEntire(t, env, workDir, "plugin", "doctor")
275		if err == nil {
276			t.Error("doctor exit code = 0 with missing dependency, want failure")
277		}
278		if !strings.Contains(stdout, `requires "semy"`) {
279			t.Errorf("doctor output = %q, want missing-dep report", stdout)
280		}
281	}
