289			{"name":"alpha","repo_url":"https://example.com/entire-alpha","description":"First letter","official":true},
290			{"name":"beta","repo_url":"https://example.com/entire-beta","description":"Second letter"}]}`)
291		env, workDir := pluginTestEnv(t, indexURL)
